mapper.select:
SELECT ingredientName
FROM (
    SELECT
        ri.INGREDIENT_NAME AS ingredientName,
        ROW_NUMBER() OVER (
            ORDER BY ri.INGREDIENT_NO ASC
        ) AS rowNo
    FROM OFT_RECIPE_INGREDIENT ri
    WHERE ri.RECIPE_NO = #{recipeNo}
)
WHERE rowNo <= #{limit}
ORDER BY rowNo
